"""Generate modules/mcp_widgets/design_css.py from the TypeScript design-system source of truth.

Usage: python scripts/sync_design_css.py [--check]
Extracts the CSS template strings of apps/web/src/modules/chat/generative-ui/design-system/index.ts
(THEME_CSS, SVG_CLASSES_CSS, FORM_STYLES_CSS) so the widget MCP server serves the same stylesheet.
--check exits 1 when the generated file is stale (used by the unit test).
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "apps/web/src/modules/chat/generative-ui/design-system/index.ts"
TARGET = ROOT / "modules/mcp_widgets/design_css.py"


def _template(src: str, name: str) -> str:
    """Return the trimmed body of `const NAME = `...`.trim();` (raises if absent)."""
    match = re.search(rf"const {name} = `(.*?)`\.trim\(\);", src, re.DOTALL)
    if not match:
        raise ValueError(f"template {name} not found in {SOURCE}")
    return match.group(1).strip()


def _tokens(src: str, name: str) -> str:
    """Render the `--*` entries of a token object as indented CSS declarations (formatTokenBlock)."""
    match = re.search(rf"const {name} = \{{(.*?)\n\}};", src, re.DOTALL)
    if not match:
        raise ValueError(f"token object {name} not found in {SOURCE}")
    pairs = re.findall(r"'(--[^']+)':\s*'([^']*)'", match.group(1))
    return "\n".join(f"  {key}: {value};" for key, value in pairs)


def build_css(src: str) -> dict[str, str]:
    """Evaluate the TS template interpolations and return THEME_CSS, SVG_CLASSES_CSS, FORM_STYLES_CSS."""
    light, dark = _tokens(src, "UMWELT_LIGHT_TOKENS"), _tokens(src, "UMWELT_DARK_TOKENS")
    theme = (
        _template(src, "THEME_CSS")
        .replace("${formatTokenBlock(UMWELT_LIGHT_TOKENS)}", light)
        .replace("${formatTokenBlock(UMWELT_DARK_TOKENS)}", dark)
        .replace("${SHARED_ALIAS_DECLARATIONS}", _template(src, "SHARED_ALIAS_DECLARATIONS"))
    )
    form = _template(src, "FORM_STYLES_WITH_STAGGER_CSS").replace(
        "${INITIAL_RENDER_STAGGER_CSS}", _template(src, "INITIAL_RENDER_STAGGER_CSS")
    )
    out = {
        "THEME_CSS": theme,
        "SVG_CLASSES_CSS": _template(src, "SVG_CLASSES_CSS"),
        "FORM_STYLES_CSS": form,
    }
    for name, css in out.items():
        if "${" in css or '"""' in css or "\\" in css:
            raise ValueError(f"{name} contains unresolved interpolation or unsupported characters")
    return out


def render() -> str:
    """Return the full text of the generated Python module."""
    parts = [
        '"""GENERATED by scripts/sync_design_css.py from the TypeScript design system; do not edit."""\n'
    ]
    for name, css in build_css(SOURCE.read_text(encoding="utf-8")).items():
        parts.append(f'\n{name} = """\n{css}\n"""\n')
    return "".join(parts)


def main(argv: list[str]) -> int:
    """Write the generated module, or with --check report staleness via the exit code."""
    text = render()
    if "--check" in argv:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != text:
            print(f"{TARGET} is out of date; run python scripts/sync_design_css.py")
            return 1
        return 0
    TARGET.write_text(text, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
